import { FhirLoader } from '../loaders/fhir-loader';
import { extractPatientFromBundle } from '../schema';

interface PatientAnalysis {
  totalPatients: number;
  birthdatePatterns: {
    futureDates: number;
    veryOldDates: number; // Before 1900
    dateRange: { earliest: string; latest: string };
    yearDistribution: Record<number, number>;
  };
  namePatterns: {
    avgFirstNameLength: number;
    avgLastNameLength: number;
    maxFirstNameLength: number;
    maxLastNameLength: number;
    numericSuffixPattern: number;
    unicodeNames: number;
    longNames: string[];
    shortNames: string[];
  };
  genderDistribution: Record<string, number>;
  addressPatterns: {
    cities: Record<string, number>;
    states: Record<string, number>;
    countries: Record<string, number>;
    postalCodePatterns: Record<string, number>;
  };
  maritalStatusDistribution: Record<string, number>;
  identifierPatterns: {
    uuidFormat: number;
    nonUuidFormat: number;
    systemPatterns: Record<string, number>;
  };
}

async function analyzePatientData() {
  console.log('=== Patient Data Outlier Analysis ===\n');

  const dataDir = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir';
  const loader = new FhirLoader(dataDir);

  // Load a sample of files for analysis
  const allFiles = loader.getAvailableFiles();
  const sampleSize = Math.min(50, allFiles.length); // Sample 50 files for performance
  const sampleFiles = [
    ...allFiles.slice(0, 10), // First 10 (smallest)
    ...allFiles.slice(Math.floor(allFiles.length / 2) - 5, Math.floor(allFiles.length / 2) + 5), // Middle 10
    ...allFiles.slice(-10), // Last 10 (largest)
    // Random additional files to reach sample size
    ...allFiles.filter((_, i) => i % Math.floor(allFiles.length / Math.max(1, sampleSize - 30)) === 0).slice(0, sampleSize - 30)
  ].slice(0, sampleSize);

  console.log(`Analyzing ${sampleFiles.length} files...`);

  const analysis: PatientAnalysis = {
    totalPatients: 0,
    birthdatePatterns: {
      futureDates: 0,
      veryOldDates: 0,
      dateRange: { earliest: '9999-12-31', latest: '1900-01-01' },
      yearDistribution: {}
    },
    namePatterns: {
      avgFirstNameLength: 0,
      avgLastNameLength: 0,
      maxFirstNameLength: 0,
      maxLastNameLength: 0,
      numericSuffixPattern: 0,
      unicodeNames: 0,
      longNames: [],
      shortNames: []
    },
    genderDistribution: {},
    addressPatterns: {
      cities: {},
      states: {},
      countries: {},
      postalCodePatterns: {}
    },
    maritalStatusDistribution: {},
    identifierPatterns: {
      uuidFormat: 0,
      nonUuidFormat: 0,
      systemPatterns: {}
    }
  };

  let totalFirstNameLength = 0;
  let totalLastNameLength = 0;

  for (const fileName of sampleFiles) {
    try {
      const result = await loader.loadBundle(fileName);
      if (!result.success || !result.bundle) continue;

      const patient = extractPatientFromBundle(result.bundle);
      if (!patient) continue;

      analysis.totalPatients++;

      // Analyze birth date
      if (patient.birthDate) {
        const birthYear = new Date(patient.birthDate).getFullYear();
        const currentYear = new Date().getFullYear();

        if (birthYear > currentYear) {
          analysis.birthdatePatterns.futureDates++;
        }
        if (birthYear < 1900) {
          analysis.birthdatePatterns.veryOldDates++;
        }

        if (patient.birthDate < analysis.birthdatePatterns.dateRange.earliest) {
          analysis.birthdatePatterns.dateRange.earliest = patient.birthDate;
        }
        if (patient.birthDate > analysis.birthdatePatterns.dateRange.latest) {
          analysis.birthdatePatterns.dateRange.latest = patient.birthDate;
        }

        analysis.birthdatePatterns.yearDistribution[birthYear] = 
          (analysis.birthdatePatterns.yearDistribution[birthYear] || 0) + 1;
      }

      // Analyze names
      if (patient.name?.[0]) {
        const name = patient.name[0];
        const firstName = name.given?.[0] || '';
        const lastName = name.family || '';

        totalFirstNameLength += firstName.length;
        totalLastNameLength += lastName.length;

        analysis.namePatterns.maxFirstNameLength = Math.max(
          analysis.namePatterns.maxFirstNameLength, 
          firstName.length
        );
        analysis.namePatterns.maxLastNameLength = Math.max(
          analysis.namePatterns.maxLastNameLength, 
          lastName.length
        );

        // Check for numeric suffix pattern
        if (/\d+$/.test(firstName) || /\d+$/.test(lastName)) {
          analysis.namePatterns.numericSuffixPattern++;
        }

        // Check for unicode characters
        if (/[^\x00-\x7F]/.test(firstName + lastName)) {
          analysis.namePatterns.unicodeNames++;
        }

        // Track very long or very short names
        const fullName = `${firstName} ${lastName}`;
        if (fullName.length > 30) {
          analysis.namePatterns.longNames.push(`${fullName} (${fileName})`);
        }
        if (fullName.length < 10) {
          analysis.namePatterns.shortNames.push(`${fullName} (${fileName})`);
        }
      }

      // Analyze gender
      if (patient.gender) {
        analysis.genderDistribution[patient.gender] = 
          (analysis.genderDistribution[patient.gender] || 0) + 1;
      }

      // Analyze address
      if (patient.address?.[0]) {
        const address = patient.address[0];

        if (address.city) {
          analysis.addressPatterns.cities[address.city] = 
            (analysis.addressPatterns.cities[address.city] || 0) + 1;
        }

        if (address.state) {
          analysis.addressPatterns.states[address.state] = 
            (analysis.addressPatterns.states[address.state] || 0) + 1;
        }

        if (address.country) {
          analysis.addressPatterns.countries[address.country] = 
            (analysis.addressPatterns.countries[address.country] || 0) + 1;
        }

        if (address.postalCode) {
          const pattern = address.postalCode.replace(/\d/g, 'N');
          analysis.addressPatterns.postalCodePatterns[pattern] = 
            (analysis.addressPatterns.postalCodePatterns[pattern] || 0) + 1;
        }
      }

      // Analyze marital status
      if (patient.maritalStatus?.text) {
        analysis.maritalStatusDistribution[patient.maritalStatus.text] = 
          (analysis.maritalStatusDistribution[patient.maritalStatus.text] || 0) + 1;
      }

      // Analyze identifiers
      if (patient.identifier) {
        for (const identifier of patient.identifier) {
          if (identifier.value) {
            const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
            if (uuidPattern.test(identifier.value)) {
              analysis.identifierPatterns.uuidFormat++;
            } else {
              analysis.identifierPatterns.nonUuidFormat++;
            }
          }

          if (identifier.system) {
            analysis.identifierPatterns.systemPatterns[identifier.system] = 
              (analysis.identifierPatterns.systemPatterns[identifier.system] || 0) + 1;
          }
        }
      }

    } catch (error) {
      console.error(`Error analyzing ${fileName}:`, error);
    }
  }

  // Calculate averages
  if (analysis.totalPatients > 0) {
    analysis.namePatterns.avgFirstNameLength = totalFirstNameLength / analysis.totalPatients;
    analysis.namePatterns.avgLastNameLength = totalLastNameLength / analysis.totalPatients;
  }

  // Print results
  console.log(`\n=== PATIENT DATA ANALYSIS RESULTS ===`);
  console.log(`Total patients analyzed: ${analysis.totalPatients}\n`);

  console.log('BIRTH DATE PATTERNS:');
  console.log(`- Future dates: ${analysis.birthdatePatterns.futureDates} (${(analysis.birthdatePatterns.futureDates/analysis.totalPatients*100).toFixed(1)}%)`);
  console.log(`- Very old dates (pre-1900): ${analysis.birthdatePatterns.veryOldDates}`);
  console.log(`- Date range: ${analysis.birthdatePatterns.dateRange.earliest} to ${analysis.birthdatePatterns.dateRange.latest}`);
  console.log(`- Year distribution (top 10):`);
  Object.entries(analysis.birthdatePatterns.yearDistribution)
    .sort(([,a], [,b]) => b - a)
    .slice(0, 10)
    .forEach(([year, count]) => console.log(`  ${year}: ${count} patients`));

  console.log('\nNAME PATTERNS:');
  console.log(`- Avg first name length: ${analysis.namePatterns.avgFirstNameLength.toFixed(1)} chars`);
  console.log(`- Avg last name length: ${analysis.namePatterns.avgLastNameLength.toFixed(1)} chars`);
  console.log(`- Max first name length: ${analysis.namePatterns.maxFirstNameLength} chars`);
  console.log(`- Max last name length: ${analysis.namePatterns.maxLastNameLength} chars`);
  console.log(`- Names with numeric suffixes: ${analysis.namePatterns.numericSuffixPattern} (${(analysis.namePatterns.numericSuffixPattern/analysis.totalPatients*100).toFixed(1)}%)`);
  console.log(`- Names with unicode chars: ${analysis.namePatterns.unicodeNames} (${(analysis.namePatterns.unicodeNames/analysis.totalPatients*100).toFixed(1)}%)`);
  if (analysis.namePatterns.longNames.length > 0) {
    console.log(`- Very long names (>30 chars): ${analysis.namePatterns.longNames.length}`);
    analysis.namePatterns.longNames.slice(0, 3).forEach(name => console.log(`  ${name}`));
  }
  if (analysis.namePatterns.shortNames.length > 0) {
    console.log(`- Very short names (<10 chars): ${analysis.namePatterns.shortNames.length}`);
    analysis.namePatterns.shortNames.slice(0, 3).forEach(name => console.log(`  ${name}`));
  }

  console.log('\nGENDER DISTRIBUTION:');
  Object.entries(analysis.genderDistribution)
    .sort(([,a], [,b]) => b - a)
    .forEach(([gender, count]) => 
      console.log(`- ${gender}: ${count} (${(count/analysis.totalPatients*100).toFixed(1)}%)`));

  console.log('\nADDRESS PATTERNS:');
  console.log(`- Cities (top 10):`);
  Object.entries(analysis.addressPatterns.cities)
    .sort(([,a], [,b]) => b - a)
    .slice(0, 10)
    .forEach(([city, count]) => console.log(`  ${city}: ${count}`));

  console.log(`- States:`);
  Object.entries(analysis.addressPatterns.states)
    .sort(([,a], [,b]) => b - a)
    .forEach(([state, count]) => console.log(`  ${state}: ${count}`));

  console.log(`- Countries:`);
  Object.entries(analysis.addressPatterns.countries)
    .sort(([,a], [,b]) => b - a)
    .forEach(([country, count]) => console.log(`  ${country}: ${count}`));

  console.log(`- Postal code patterns:`);
  Object.entries(analysis.addressPatterns.postalCodePatterns)
    .sort(([,a], [,b]) => b - a)
    .slice(0, 5)
    .forEach(([pattern, count]) => console.log(`  ${pattern}: ${count}`));

  if (Object.keys(analysis.maritalStatusDistribution).length > 0) {
    console.log('\nMARITAL STATUS:');
    Object.entries(analysis.maritalStatusDistribution)
      .sort(([,a], [,b]) => b - a)
      .forEach(([status, count]) => console.log(`- ${status}: ${count}`));
  }

  console.log('\nIDENTIFIER PATTERNS:');
  console.log(`- UUID format: ${analysis.identifierPatterns.uuidFormat}`);
  console.log(`- Non-UUID format: ${analysis.identifierPatterns.nonUuidFormat}`);
  console.log(`- Systems:`);
  Object.entries(analysis.identifierPatterns.systemPatterns)
    .sort(([,a], [,b]) => b - a)
    .forEach(([system, count]) => console.log(`  ${system}: ${count}`));

  return analysis;
}

if (require.main === module) {
  analyzePatientData().catch(console.error);
}

export { analyzePatientData };

import { FhirLoader } from '../loaders/fhir-loader';
import { extractResourcesByType } from '../schema';
import type { ObservationType } from '../schema';

interface ObservationAnalysis {
  totalObservations: number;
  statusDistribution: Record<string, number>;
  categoryDistribution: Record<string, number>;
  valueTypes: {
    quantity: number;
    string: number;
    boolean: number;
    codeableConcept: number;
    missing: number;
  };
  vitalSigns: {
    height: { values: number[]; unit: string; outliers: Array<{value: number, file: string}> };
    weight: { values: number[]; unit: string; outliers: Array<{value: number, file: string}> };
    bloodPressure: { 
      systolic: { values: number[]; outliers: Array<{value: number, file: string}> };
      diastolic: { values: number[]; outliers: Array<{value: number, file: string}> };
    };
    heartRate: { values: number[]; unit: string; outliers: Array<{value: number, file: string}> };
    temperature: { values: number[]; unit: string; outliers: Array<{value: number, file: string}> };
    respiratoryRate: { values: number[]; unit: string; outliers: Array<{value: number, file: string}> };
  };
  labValues: {
    cholesterol: { values: number[]; outliers: Array<{value: number, file: string}> };
    glucose: { values: number[]; outliers: Array<{value: number, file: string}> };
    hemoglobin: { values: number[]; outliers: Array<{value: number, file: string}> };
  };
  codePatterns: Record<string, number>;
  unitPatterns: Record<string, number>;
  extremeValues: Array<{type: string, value: number, unit: string, file: string}>;
}

function detectOutliers(values: number[]): { outliers: number[]; q1: number; q3: number; iqr: number } {
  if (values.length === 0) return { outliers: [], q1: 0, q3: 0, iqr: 0 };

  const sorted = [...values].sort((a, b) => a - b);
  const q1Index = Math.floor(sorted.length * 0.25);
  const q3Index = Math.floor(sorted.length * 0.75);
  const q1 = sorted[q1Index];
  const q3 = sorted[q3Index];
  const iqr = q3 - q1;
  const lowerBound = q1 - 1.5 * iqr;
  const upperBound = q3 + 1.5 * iqr;

  const outliers = values.filter(v => v < lowerBound || v > upperBound);
  return { outliers, q1, q3, iqr };
}

async function analyzeObservations() {
  console.log('=== Observation Data Outlier Analysis ===\n');

  const dataDir = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir';
  const loader = new FhirLoader(dataDir);

  // Load a sample of files for analysis
  const allFiles = loader.getAvailableFiles();
  const sampleFiles = [
    ...allFiles.slice(0, 10), // Small files
    ...allFiles.slice(Math.floor(allFiles.length / 2) - 5, Math.floor(allFiles.length / 2) + 5), // Medium files
    ...allFiles.slice(-5) // Large files
  ];

  console.log(`Analyzing observations in ${sampleFiles.length} files...`);

  const analysis: ObservationAnalysis = {
    totalObservations: 0,
    statusDistribution: {},
    categoryDistribution: {},
    valueTypes: {
      quantity: 0,
      string: 0,
      boolean: 0,
      codeableConcept: 0,
      missing: 0
    },
    vitalSigns: {
      height: { values: [], unit: '', outliers: [] },
      weight: { values: [], unit: '', outliers: [] },
      bloodPressure: { 
        systolic: { values: [], outliers: [] },
        diastolic: { values: [], outliers: [] }
      },
      heartRate: { values: [], unit: '', outliers: [] },
      temperature: { values: [], unit: '', outliers: [] },
      respiratoryRate: { values: [], unit: '', outliers: [] }
    },
    labValues: {
      cholesterol: { values: [], outliers: [] },
      glucose: { values: [], outliers: [] },
      hemoglobin: { values: [], outliers: [] }
    },
    codePatterns: {},
    unitPatterns: {},
    extremeValues: []
  };

  const heightCodes = ['8302-2', '3137-7'];
  const weightCodes = ['29463-7', '3141-9'];
  const bpCodes = ['85354-9', '8480-6', '8462-4']; // BP panel, systolic, diastolic
  const heartRateCodes = ['8867-4'];
  const temperatureCodes = ['8310-5'];
  const respiratoryCodes = ['9279-1'];
  const cholesterolCodes = ['2093-3', '14647-2'];
  const glucoseCodes = ['2339-0', '33747-0'];
  const hemoglobinCodes = ['718-7'];

  for (const fileName of sampleFiles) {
    try {
      const result = await loader.loadBundle(fileName);
      if (!result.success || !result.bundle) continue;

      const observations = extractResourcesByType(result.bundle, 'Observation') as ObservationType[];

      for (const obs of observations) {
        analysis.totalObservations++;

        // Analyze status
        if (obs.status) {
          analysis.statusDistribution[obs.status] = 
            (analysis.statusDistribution[obs.status] || 0) + 1;
        }

        // Analyze category
        if (obs.category?.[0]?.coding?.[0]?.display) {
          const category = obs.category[0].coding[0].display;
          analysis.categoryDistribution[category] = 
            (analysis.categoryDistribution[category] || 0) + 1;
        }

        // Analyze value types
        if (obs.valueQuantity) {
          analysis.valueTypes.quantity++;

          const value = obs.valueQuantity.value;
          const unit = obs.valueQuantity.unit || obs.valueQuantity.code || '';
          const code = obs.code.coding?.[0]?.code;

          if (value !== undefined && code) {
            // Track units
            if (unit) {
              analysis.unitPatterns[unit] = (analysis.unitPatterns[unit] || 0) + 1;
            }

            // Categorize vital signs
            if (heightCodes.includes(code)) {
              analysis.vitalSigns.height.values.push(value);
              analysis.vitalSigns.height.unit = unit;
            } else if (weightCodes.includes(code)) {
              analysis.vitalSigns.weight.values.push(value);
              analysis.vitalSigns.weight.unit = unit;
            } else if (code === '8480-6') { // Systolic BP
              analysis.vitalSigns.bloodPressure.systolic.values.push(value);
            } else if (code === '8462-4') { // Diastolic BP
              analysis.vitalSigns.bloodPressure.diastolic.values.push(value);
            } else if (heartRateCodes.includes(code)) {
              analysis.vitalSigns.heartRate.values.push(value);
              analysis.vitalSigns.heartRate.unit = unit;
            } else if (temperatureCodes.includes(code)) {
              analysis.vitalSigns.temperature.values.push(value);
              analysis.vitalSigns.temperature.unit = unit;
            } else if (respiratoryCodes.includes(code)) {
              analysis.vitalSigns.respiratoryRate.values.push(value);
              analysis.vitalSigns.respiratoryRate.unit = unit;
            } else if (cholesterolCodes.includes(code)) {
              analysis.labValues.cholesterol.values.push(value);
            } else if (glucoseCodes.includes(code)) {
              analysis.labValues.glucose.values.push(value);
            } else if (hemoglobinCodes.includes(code)) {
              analysis.labValues.hemoglobin.values.push(value);
            }

            // Track extreme values
            if (value > 10000 || value < 0) {
              analysis.extremeValues.push({
                type: obs.code.text || obs.code.coding?.[0]?.display || 'Unknown',
                value,
                unit,
                file: fileName
              });
            }
          }
        } else if (obs.valueString) {
          analysis.valueTypes.string++;
        } else if (obs.valueBoolean !== undefined) {
          analysis.valueTypes.boolean++;
        } else if (obs.valueCodeableConcept) {
          analysis.valueTypes.codeableConcept++;
        } else {
          analysis.valueTypes.missing++;
        }

        // Analyze codes
        if (obs.code.coding?.[0]?.code) {
          const code = obs.code.coding[0].code;
          analysis.codePatterns[code] = (analysis.codePatterns[code] || 0) + 1;
        }
      }

    } catch (error) {
      console.error(`Error analyzing observations in ${fileName}:`, error);
    }
  }

  // Detect outliers for vital signs
  const detectVitalOutliers = (values: number[], type: string, fileName: string) => {
    const { outliers } = detectOutliers(values);
    return outliers.map(value => ({ value, file: fileName }));
  };

  // Find outliers for each vital sign type
  analysis.vitalSigns.height.outliers = detectVitalOutliers(analysis.vitalSigns.height.values, 'height', 'multiple');
  analysis.vitalSigns.weight.outliers = detectVitalOutliers(analysis.vitalSigns.weight.values, 'weight', 'multiple');
  analysis.vitalSigns.bloodPressure.systolic.outliers = detectVitalOutliers(analysis.vitalSigns.bloodPressure.systolic.values, 'systolic', 'multiple');
  analysis.vitalSigns.bloodPressure.diastolic.outliers = detectVitalOutliers(analysis.vitalSigns.bloodPressure.diastolic.values, 'diastolic', 'multiple');
  analysis.vitalSigns.heartRate.outliers = detectVitalOutliers(analysis.vitalSigns.heartRate.values, 'heartRate', 'multiple');
  analysis.vitalSigns.temperature.outliers = detectVitalOutliers(analysis.vitalSigns.temperature.values, 'temperature', 'multiple');
  analysis.vitalSigns.respiratoryRate.outliers = detectVitalOutliers(analysis.vitalSigns.respiratoryRate.values, 'respiratoryRate', 'multiple');

  // Print results
  console.log(`\n=== OBSERVATION ANALYSIS RESULTS ===`);
  console.log(`Total observations analyzed: ${analysis.totalObservations}\n`);

  console.log('STATUS DISTRIBUTION:');
  Object.entries(analysis.statusDistribution)
    .sort(([,a], [,b]) => b - a)
    .forEach(([status, count]) => 
      console.log(`- ${status}: ${count} (${(count/analysis.totalObservations*100).toFixed(1)}%)`));

  console.log('\nCATEGORY DISTRIBUTION:');
  Object.entries(analysis.categoryDistribution)
    .sort(([,a], [,b]) => b - a)
    .slice(0, 10)
    .forEach(([category, count]) => 
      console.log(`- ${category}: ${count} (${(count/analysis.totalObservations*100).toFixed(1)}%)`));

  console.log('\nVALUE TYPES:');
  Object.entries(analysis.valueTypes)
    .forEach(([type, count]) => 
      console.log(`- ${type}: ${count} (${(count/analysis.totalObservations*100).toFixed(1)}%)`));

  console.log('\nVITAL SIGNS ANALYSIS:');

  // Height analysis
  if (analysis.vitalSigns.height.values.length > 0) {
    const heights = analysis.vitalSigns.height.values;
    console.log(`- Height (${analysis.vitalSigns.height.unit}): ${heights.length} measurements`);
    console.log(`  Range: ${Math.min(...heights).toFixed(1)} - ${Math.max(...heights).toFixed(1)}`);
    console.log(`  Mean: ${(heights.reduce((a, b) => a + b, 0) / heights.length).toFixed(1)}`);
    if (analysis.vitalSigns.height.outliers.length > 0) {
      console.log(`  Outliers: ${analysis.vitalSigns.height.outliers.length}`);
      analysis.vitalSigns.height.outliers.slice(0, 3).forEach(o => 
        console.log(`    ${o.value} ${analysis.vitalSigns.height.unit}`));
    }
  }

  // Weight analysis
  if (analysis.vitalSigns.weight.values.length > 0) {
    const weights = analysis.vitalSigns.weight.values;
    console.log(`- Weight (${analysis.vitalSigns.weight.unit}): ${weights.length} measurements`);
    console.log(`  Range: ${Math.min(...weights).toFixed(1)} - ${Math.max(...weights).toFixed(1)}`);
    console.log(`  Mean: ${(weights.reduce((a, b) => a + b, 0) / weights.length).toFixed(1)}`);
    if (analysis.vitalSigns.weight.outliers.length > 0) {
      console.log(`  Outliers: ${analysis.vitalSigns.weight.outliers.length}`);
    }
  }

  // Blood pressure analysis
  if (analysis.vitalSigns.bloodPressure.systolic.values.length > 0) {
    const systolic = analysis.vitalSigns.bloodPressure.systolic.values;
    const diastolic = analysis.vitalSigns.bloodPressure.diastolic.values;
    console.log(`- Blood Pressure (mmHg): ${systolic.length} systolic, ${diastolic.length} diastolic`);
    console.log(`  Systolic range: ${Math.min(...systolic)} - ${Math.max(...systolic)}`);
    if (diastolic.length > 0) {
      console.log(`  Diastolic range: ${Math.min(...diastolic)} - ${Math.max(...diastolic)}`);
    }
    if (analysis.vitalSigns.bloodPressure.systolic.outliers.length > 0) {
      console.log(`  Systolic outliers: ${analysis.vitalSigns.bloodPressure.systolic.outliers.length}`);
    }
  }

  // Heart rate analysis
  if (analysis.vitalSigns.heartRate.values.length > 0) {
    const hr = analysis.vitalSigns.heartRate.values;
    console.log(`- Heart Rate (${analysis.vitalSigns.heartRate.unit}): ${hr.length} measurements`);
    console.log(`  Range: ${Math.min(...hr)} - ${Math.max(...hr)}`);
    console.log(`  Mean: ${(hr.reduce((a, b) => a + b, 0) / hr.length).toFixed(1)}`);
  }

  console.log('\nMOST COMMON OBSERVATION CODES:');
  Object.entries(analysis.codePatterns)
    .sort(([,a], [,b]) => b - a)
    .slice(0, 10)
    .forEach(([code, count]) => console.log(`- ${code}: ${count}`));

  console.log('\nMOST COMMON UNITS:');
  Object.entries(analysis.unitPatterns)
    .sort(([,a], [,b]) => b - a)
    .slice(0, 10)
    .forEach(([unit, count]) => console.log(`- ${unit}: ${count}`));

  if (analysis.extremeValues.length > 0) {
    console.log('\nEXTREME VALUES (>10000 or <0):');
