function extractNumericDose(doseText: string): { value: number; unit: string } | null {
  // Common patterns for doses
  const patterns = [
    /(\d+(?:\.\d+)?)\s*(mg|g|mcg|μg|units?|ml|tablets?|capsules?)/i,
    /(\d+(?:\.\d+)?)\s*(milligrams?|grams?|micrograms?|milliliters?)/i
  ];

  for (const pattern of patterns) {
    const match = doseText.match(pattern);
    if (match) {
      return {
        value: parseFloat(match[1]),
        unit: match[2].toLowerCase()
      };
    }
  }
  return null;
}

function parseDuration(text: string): number | null {
  // Extract duration in days
  const patterns = [
    /(\d+)\s*days?/i,
    /(\d+)\s*weeks?/i,
    /(\d+)\s*months?/i,
    /(\d+)\s*years?/i
  ];

  const dayMatch = text.match(patterns[0]);
  if (dayMatch) return parseInt(dayMatch[1]);

  const weekMatch = text.match(patterns[1]);
  if (weekMatch) return parseInt(weekMatch[1]) * 7;

  const monthMatch = text.match(patterns[2]);
  if (monthMatch) return parseInt(monthMatch[1]) * 30;

  const yearMatch = text.match(patterns[3]);
  if (yearMatch) return parseInt(yearMatch[1]) * 365;

  return null;
}

