import { analyzePatientData } from './patient-data-outliers';
import { analyzeObservations } from './observation-outliers';
import { analyzeMedications } from './medication-outliers';
import { analyzeFinancials } from './financial-outliers';

async function generateOutlierSummary() {
  console.log('=== COMPREHENSIVE OUTLIER ANALYSIS SUMMARY ===\n');
  console.log('Running all analysis scripts to generate comprehensive dataset insights...\n');

  try {
    // Run all analyses
    console.log('1. Patient Data Analysis...');
    const patientAnalysis = await analyzePatientData();

    console.log('\n2. Observation Analysis...');
    const observationAnalysis = await analyzeObservations();

    console.log('\n3. Medication Analysis...');
    const medicationAnalysis = await analyzeMedications();

    console.log('\n4. Financial Analysis...');
    const financialAnalysis = await analyzeFinancials();

    // Generate summary insights
    console.log('\n' + '='.repeat(80));
    console.log('DATASET QUALITY & OUTLIER SUMMARY');
    console.log('='.repeat(80));

    console.log('\n📊 SAMPLE SIZE:');
    console.log(`- Patients analyzed: ${patientAnalysis.totalPatients}`);
    console.log(`- Observations analyzed: ${observationAnalysis.totalObservations}`);
    console.log(`- Medication requests: ${medicationAnalysis.totalMedicationRequests}`);
    console.log(`- Claims/EOBs: ${financialAnalysis.totalClaims}/${financialAnalysis.totalEOBs}`);

    console.log('\n🚨 KEY OUTLIERS DETECTED:');

    // Patient outliers
    console.log('\nPatient Data:');
    if (patientAnalysis.birthdatePatterns.futureDates > 0) {
      console.log(`- ⚠️  Future birth dates: ${patientAnalysis.birthdatePatterns.futureDates} patients`);
    }
    console.log(`- ℹ️  100% synthetic names with numeric suffixes (expected)`);
    console.log(`- ℹ️  ${patientAnalysis.namePatterns.unicodeNames} patients (${(patientAnalysis.namePatterns.unicodeNames/patientAnalysis.totalPatients*100).toFixed(1)}%) have unicode names`);
    console.log(`- ℹ️  All patients from Boston, MA, US (synthetic data constraint)`);

    // Observation outliers
    console.log('\nObservation Data:');
    if (observationAnalysis.vitalSigns.height.outliers.length > 0) {
      const minHeight = Math.min(...observationAnalysis.vitalSigns.height.values);
      const maxHeight = Math.max(...observationAnalysis.vitalSigns.height.values);
      console.log(`- ⚠️  Height outliers: ${observationAnalysis.vitalSigns.height.outliers.length} measurements`);
      console.log(`  Range: ${minHeight} - ${maxHeight} cm (some very short heights detected)`);
    }
    if (observationAnalysis.vitalSigns.weight.outliers.length > 0) {
      const minWeight = Math.min(...observationAnalysis.vitalSigns.weight.values);
      const maxWeight = Math.max(...observationAnalysis.vitalSigns.weight.values);
      console.log(`- ℹ️  Weight range: ${minWeight} - ${maxWeight} kg (includes pediatric patients)`);
    }
    if (observationAnalysis.extremeValues.length > 0) {
      console.log(`- ⚠️  Extreme values: ${observationAnalysis.extremeValues.length} measurements with values >10000 or <0`);
      console.log(`  Note: Negative bone density T-scores are clinically normal`);
    }

    // Medication outliers
    console.log('\nMedication Data:');
    const stoppedPercentage = medicationAnalysis.statusDistribution['stopped'] / medicationAnalysis.totalMedicationRequests * 100;
    console.log(`- ℹ️  ${stoppedPercentage.toFixed(1)}% of medications have "stopped" status`);
    console.log(`- ℹ️  Most common frequency: 1x per day (${medicationAnalysis.dosagePatterns.frequencies['1x per d'] || 0} medications)`);
    if (medicationAnalysis.doseRanges.extremeLow.length > 0) {
      console.log(`- ⚠️  Extremely low doses: ${medicationAnalysis.doseRanges.extremeLow.length} medications`);
    }
    if (medicationAnalysis.doseRanges.extremeHigh.length > 0) {
      console.log(`- ⚠️  Extremely high doses: ${medicationAnalysis.doseRanges.extremeHigh.length} medications`);
    }

    // Financial outliers
    console.log('\nFinancial Data:');
    const claimAmounts = financialAnalysis.amounts.claimAmounts;
    const maxClaimAmount = Math.max(...claimAmounts);
    const deniedPercentage = financialAnalysis.paymentPatterns.deniedClaims / financialAnalysis.totalClaims * 100;
    console.log(`- ℹ️  Claim amounts range: $0 - $${maxClaimAmount.toFixed(2)}`);
    console.log(`- ℹ️  ${deniedPercentage.toFixed(1)}% of claims denied (payment amount = $0)`);
    console.log(`- ℹ️  ${financialAnalysis.amounts.zeroAmounts} zero-amount transactions`);
    if (financialAnalysis.amounts.extremelyHigh.length > 0) {
      console.log(`- ⚠️  Extremely high amounts: ${financialAnalysis.amounts.extremelyHigh.length} transactions >$50,000`);
    }
    if (financialAnalysis.amounts.negativeAmounts.length > 0) {
      console.log(`- ⚠️  Negative amounts: ${financialAnalysis.amounts.negativeAmounts.length} transactions`);
    }

    console.log('\n📋 SCHEMA RECOMMENDATIONS:');
    console.log('\nBased on outlier analysis, consider these schema constraints:');

    console.log('\n1. Patient Resource:');
    console.log('   - birthDate: constrain to 1900-2030 range');
    console.log('   - gender: enum [male, female] (only observed values)');
    console.log('   - name: expect numeric suffix pattern for synthetic data');
    console.log('   - address.country: likely always "US" in this dataset');

    console.log('\n2. Observation Resource:');
    console.log('   - status: likely always "final" in this dataset');
    console.log('   - valueQuantity.value: add reasonable ranges per observation type');
    console.log('   - height: 50-250 cm range (pediatric to adult)');
    console.log('   - weight: 2-200 kg range (pediatric to adult)');
    console.log('   - heart rate: 40-200 bpm range');
    console.log('   - allow negative values for bone density T-scores');

    console.log('\n3. MedicationRequest Resource:');
    console.log('   - status: enum [active, stopped] (primary observed values)');
    console.log('   - intent: likely always "order" in this dataset');
    console.log('   - dosage frequency: 1-4x per day most common');

    console.log('\n4. Claim/EOB Resources:');
    console.log('   - status: likely always "active" in this dataset');
    console.log('   - amounts: $0-$100,000 reasonable range');
    console.log('   - currency: likely always "USD" in this dataset');
    console.log('   - allow zero amounts for denied claims');

    console.log('\n5. General Patterns:');
    console.log('   - All UUIDs follow standard format');
    console.log('   - Geographic data constrained to Boston area');
    console.log('   - Date ranges span 1920-2025 (synthetic data)');
    console.log('   - Multiple language support (English/Spanish names)');

    return {
      patientAnalysis,
      observationAnalysis,
      medicationAnalysis,
      financialAnalysis
    };

  } catch (error) {
    console.error('Error running comprehensive analysis:', error);
    throw error;
  }
}

if (require.main === module) {
  generateOutlierSummary().catch(console.error);
}

export { generateOutlierSummary };

